import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.CnJ-JtFX.js";const k=JSON.parse('{"title":"EP.17 递归渲染的魔法","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.17-mini-lowcode-renderer.md","filePath":"comics/EP.17-mini-lowcode-renderer.md","lastUpdated":1792683644000}'),t={name:"comics/EP.17-mini-lowcode-renderer.md"};function p(l,s,h,o,r,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="ep-17-递归渲染的魔法" tabindex="-1">EP.17 递归渲染的魔法 <a class="header-anchor" href="#ep-17-递归渲染的魔法" aria-label="Permalink to &quot;EP.17 递归渲染的魔法&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/17-mini-lowcode-renderer">guide/17-mini-lowcode-renderer</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>Schema 树</strong>：一棵 page → container → text/button 的 Schema 树摆在像素酱面前，她要把它变成真实页面。</li><li><strong>递归渲染</strong>：像素酱演示 render(node) 函数——里面调 render(child)，像套娃一样一层层往里钻。</li><li><strong>表达式替换</strong>：标签君看到 Schema 里的 <code>$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;</code> 被替换成了「张三」，惊讶数据里的表达式居然能在渲染时求值。</li><li><strong>终止条件</strong>：码叔提醒——递归必须有终止条件（children 为空时停止），否则无限套娃导致栈溢出。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-schema-是树-不是列表" tabindex="-1">第一格：Schema 是树，不是列表 <a class="header-anchor" href="#第一格-schema-是树-不是列表" aria-label="Permalink to &quot;第一格：Schema 是树，不是列表&quot;">​</a></h3><p>Schema 的核心结构是<strong>递归树</strong>：每个节点都有 <code>type</code>、<code>props</code>，可能有 <code>children</code>。<code>children</code> 里的每个元素又是一个完整的 Schema 节点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>page</span></span>
<span class="line"><span>├── container</span></span>
<span class="line"><span>│   ├── text</span></span>
<span class="line"><span>│   └── button</span></span>
<span class="line"><span>└── container</span></span>
<span class="line"><span>    └── ...</span></span></code></pre></div><p>Renderer 面对的不是一个扁平列表，而是一棵任意深度的树。这决定了 Renderer 的实现方式必须是<strong>递归</strong>。</p><h3 id="第二格-递归函数的结构" tabindex="-1">第二格：递归函数的结构 <a class="header-anchor" href="#第二格-递归函数的结构" aria-label="Permalink to &quot;第二格：递归函数的结构&quot;">​</a></h3><p>递归渲染函数的结构非常简洁：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SchemaNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> component</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> resolveComponent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(node.type);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> children</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (node.children </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(render);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> h</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(component, node.props, children);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>三个步骤：</p><ol><li>根据 <code>node.type</code> 找到对应的组件实现；</li><li>递归渲染所有子节点，得到子 VNode 数组；</li><li>用 <code>h()</code> 把当前组件和子节点组装成 VNode。</li></ol><p>这个函数之所以能工作，是因为 Schema 的结构是递归的，render 的结构也是递归的，两者同构。</p><h3 id="第三格-表达式求值" tabindex="-1">第三格：表达式求值 <a class="header-anchor" href="#第三格-表达式求值" aria-label="Permalink to &quot;第三格：表达式求值&quot;">​</a></h3><p>Schema 的 <code>props</code> 里可以写表达式 <code>$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;</code>。Renderer 在渲染前会遍历 props，遇到 <code>$&amp;#123;&amp;#123; &amp;#125;&amp;#125;</code> 包裹的表达式，就用**上下文（context）**里的数据求值替换。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上下文: { name: &quot;张三&quot; }</span></span>
<span class="line"><span>Schema:  { text: &quot;\${{ name }}&quot; }</span></span>
<span class="line"><span>渲染后:  { text: &quot;张三&quot; }</span></span></code></pre></div><p>表达式求值的本质是：把数据里的字符串模板，用运行时上下文替换成实际值。这让同一份 Schema 可以渲染出不同的内容（数据驱动的体现）。</p><h3 id="第四格-递归的终止条件" tabindex="-1">第四格：递归的终止条件 <a class="header-anchor" href="#第四格-递归的终止条件" aria-label="Permalink to &quot;第四格：递归的终止条件&quot;">​</a></h3><p>递归必须有<strong>终止条件</strong>，否则会无限调用自己，最终栈溢出（Stack Overflow）。</p><p>Renderer 的终止条件是：<code>node.children</code> 为空（或不存在）。此时不再递归调用 render，直接返回叶子节点的 VNode。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 终止条件：没有子节点</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node.children </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node.children.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> h</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(component, node.props);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 递归</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> children</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node.children.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(render);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> h</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(component, node.props, children);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>没有终止条件的递归 = 死循环 = 栈溢出。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>忘记终止条件</strong>：递归函数最常见的 bug 就是没有终止条件，导致栈溢出。写递归前先想清楚「什么时候停」。</li><li><strong>循环引用导致无限递归</strong>：如果 Schema 里出现循环引用（A 的 children 包含 A），递归会无限进行。需要做环检测或限制最大深度。</li><li><strong>表达式求值的沙箱问题</strong>：直接 <code>eval</code> 表达式有安全风险，应该用 <code>new Function</code> 或专门的表达式解析器，限制可访问的变量。</li><li><strong>上下文丢失</strong>：递归时要把上下文（数据、作用域）正确传递给子节点，否则表达式找不到变量。</li><li><strong>组件注册缺失</strong>：<code>resolveComponent(node.type)</code> 如果找不到组件，应该降级渲染而不是崩溃。</li><li><strong>props 里的表达式和字面量混淆</strong>：要区分 <code>&quot;$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;&quot;</code>（表达式）和 <code>&quot;&amp;#123;&amp;#123; name &amp;#125;&amp;#125;&quot;</code>（普通字符串），用 <code>$&amp;#123;&amp;#123; &amp;#125;&amp;#125;</code> 作为表达式标记。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 为什么 Renderer 必须用递归实现，而不是循环？</b></summary><p>因为 Schema 是<strong>递归树结构</strong>——每个节点的 children 又是一组完整的 Schema 节点，深度可以是任意的。</p><p>循环只能处理扁平结构（一层），而递归能天然匹配树的嵌套结构。render 函数的逻辑和 Schema 的结构同构：节点有 children 就递归处理 children，没有就停止。</p><p>如果用循环处理树，需要自己维护一个栈来模拟递归，代码反而更复杂。递归是处理树结构最自然的方式。</p></details><details><summary><b>2. Renderer 里的表达式 \`\${{ name }}\` 是怎么被替换成「张三」的？</b></summary><p>分三步：</p><ol><li><strong>识别表达式</strong>：Renderer 遍历 props，发现值是 <code>&quot;$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;&quot;</code> 格式的字符串；</li><li><strong>解析表达式</strong>：取出 <code>&amp;#123;&amp;#123; &amp;#125;&amp;#125;</code> 里的表达式 <code>name</code>，在上下文（context）里查找 <code>name</code> 的值；</li><li><strong>替换</strong>：用上下文里的值（&quot;张三&quot;）替换整个 <code>$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;</code>。</li></ol><p>上下文通常包含页面的数据对象、当前节点的 props、全局变量等。表达式求值的本质是「数据 + 模板 = 最终值」，这也是「数据驱动视图」的体现。</p><p>生产级实现会用专门的表达式解析器（如 jsep），而不是简单的字符串替换，以支持复杂表达式（算术、逻辑、函数调用）。</p></details><details><summary><b>3. 递归渲染如果没有终止条件会发生什么？怎么避免？</b></summary><p>没有终止条件的递归会<strong>无限调用自己</strong>，每次调用都会在调用栈上压入一帧，最终超出栈的容量限制，抛出 <code>Stack Overflow</code> 错误，页面崩溃。</p><p>避免方法：</p><ol><li><strong>明确终止条件</strong>：Renderer 的终止条件是 <code>node.children</code> 为空，此时直接返回叶子 VNode，不再递归；</li><li><strong>环检测</strong>：如果 Schema 可能存在循环引用（A → B → A），需要在递归时记录已访问的节点路径，遇到重复节点就停止；</li><li><strong>最大深度限制</strong>：设置一个最大递归深度（如 100），超过就报错，防止异常 Schema 导致崩溃。</li></ol><p>核心原则：<strong>写递归前先想清楚「什么时候停」</strong>。</p></details>`,30)])])}const g=a(t,[["render",p]]);export{k as __pageData,g as default};
